eturn e[r]>=3&&u>=2?{language:r,confidence:"strong",scores:e}:e[r]>=2&&u>=1?{language:r,confidence:"weak",scores:e}:{language:null,confidence:"none",scores:e}}function f(n,a){let e=d(n);return a?!e.language||e.confidence==="none"||e.language===a?a:e.confidence==="explicit"||e.confidence==="strong"?e.language:a:e.language}function h(n,a){let e=a.map(o=>d(o).language);return e.some(o=>o!==null&&o!==n)?{allowed:!1,expected_language:n,detected_languages:e,reason:"response_language_mismatch"}:{allowed:!0,expected_language:n,detected_languages:e,reason:e.every(o=>o===null)?"neutral_text":"matched"}}

return {"detectLanguage":d,"explicitLanguageRequest":m,"resolveLeadLanguage":f,"validateResponseLanguages":h};})();

if($("CENTRAL DE CONTROLE").first().json.cerebro_teste_revisado!==true)throw new Error("review_isolated_brain_before_model");
const items = await (async()=>{
const r = $('LEXIA | Registro individual confirmado').first().json;
const batch = $('LEXIA | Lote autorizado').first().json;
const rows = $('Agrupar Histórico').first().json.data || [];
const cfg = $('LEXIA | Configuracao de contexto').first().json;
const snapshot = $('LEXIA | Estado e contexto duraveis').first().json;
if (!cfg.prompt_template || cfg.environment !== r.environment || cfg.cliente_slug !== r.cliente_slug || cfg.status !== 'active') throw new Error('context_config_unavailable');
for (const m of rows) if (m.omni_conversation_id !== r.conversation_id || m.cliente_slug !== r.cliente_slug) throw new Error('history_scope_mismatch');
const messages = rows.filter(m => batch.out_mensagem_ids.includes(m.id));
if (messages.length !== batch.out_mensagem_ids.length) throw new Error('batch_source_messages_missing');
const previous = snapshot.context?.operational_context || {};
const legacy = {tipo_assunto:previous.intent || 'indefinido',confianca:previous.confidence ?? 0,resumo_contexto:previous.summary || '',dados:snapshot.context?.company_fields || {}};
return [{json:{scope:{environment:r.environment,cliente_slug:r.cliente_slug,channel:r.channel,account_ref:r.account_ref,conversation_ref:r.conversation_ref},
  context_call_id:batch.invocation_id,config_version:cfg.config_version,company_fields_schema:cfg.company_fields_schema,
  source_message_ids:messages.map(m=>m.id),state:snapshot.state,context_version:Number(snapshot.context?.context_version || 0),
  mensagem_actual:messages.map(m=>m.conteudo || '['+m.tipo+']').join('\n\n'),contacto_id:$('Unificar Contacto').first().json.id,nome_contacto:r.nome,telefone:r.telefone,
  identificador_conversa:r.identificador_conversa,historico_mensagens:rows,contexto_activo:JSON.stringify(legacy),prompt_template:cfg.prompt_template},pairedItem:{item:0}}];})();
const prev = $("LEXIA | Estado e contexto duraveis").first().json.context?.operational_context?.language?.split("-")[0];
for(const i of items) {i.json.expected_language=LexiaLanguage.resolveLeadLanguage(i.json.mensagem_actual,["pt","en","es"].includes(prev)?prev:null);}
return items;

function parseBody(raw) {
  if (!raw) return {};
  if (typeof raw === 'string') {
    try { return JSON.parse(raw); } catch (e) { return {}; }
  }
  return raw;
}

function normalizarTexto(valor) {
  return String(valor || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function textoParaChave(valor) {
  return normalizarTexto(valor)
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 180);
}

// ============================================================
// DETECÇÃO DE IDIOMA — heurística por palavras marcadoras.
// Usada pelo follow-up rápido para escolher o idioma da
// mensagem a partir da legenda do anúncio (cartão ig_post).
// Empate ou nenhum marcador → inglês (padrão da operação).
// ============================================================
function detectarIdioma(t) {
  const s = ' ' + normalizarTexto(t) + ' ';
  const marcadores = {
    pt: [' voce ', ' pele ', ' nao ', ' para ', ' cuidado ', ' tratamentos ', ' agendamento ', ' nossa ', ' esta ', ' comente '],
    es: [' usted ', ' piel ', ' cita ', ' tratamientos ', ' nuestra ', ' comenta ', ' tu ', ' aqui '],
    en: [' the ', ' your ', ' skin ', ' and ', ' care ', ' treatments ', ' appointment ', ' with ', ' you ', ' comment ']
  };
  let melhor = 'en';
  let melhorPontos = 0;
  for (const [idioma, palavras] of Object.entries(marcadores)) {
    const pontos = palavras.filter(p => s.includes(p)).length;
    if (pontos > melhorPontos) { melhorPontos = pontos; melhor = idioma; }
  }
  return melhor;
}

const body = parseBody($json.body || {});

const entry = (body.entry || [])[0] || {};
const messaging = (entry.messaging || [])[0] || {};

// ============================================================
// MENSAGEM EDITADA (message_edit) — recuperar o texto pela API.
// Quando o cliente EDITA uma DM, a Meta manda um evento
// "message_edit" que traz APENAS o mid (sem texto) — e às vezes
// o evento da mensagem original nem chega (caso real: lead do
// anúncio ficou sem resposta). Aqui buscamos o texto ATUAL da
// mensagem na Graph API pelo mid e seguimos o fluxo como
// mensagem normal. Se a busca falhar ou vier sem texto, o
// evento é descartado como antes (sem erro, sem resposta vazia).
// TOKENS (copiar do Config Cliente Lexia — manter em sincronia
// com o "Preparar Perfil Meta")
// ============================================================
// Edicoes nao originam uma nova resposta; sem chamadas HTTP ou tokens inline.
if(messaging.message_edit)return [];
const postback =
  (!messaging.message && messaging.postback && typeof messaging.postback === 'object')
    ? messaging.postback
    : null;

// ============================================================
// FILTRO DE EVENTOS — só mensagens reais (ou postbacks) passam.
// Leituras, entregas, reações, mensagens apagadas e conteúdos
// não suportados NUNCA devem chegar ao agente: cada um deles
// virava uma "mensagem vazia" e o agente respondia de novo.
// ============================================================
if (!postback && (!messaging.message || typeof messaging.message !== 'object')) return [];

const message = messaging.message || {};

if (message.reaction || message.is_deleted === true || message.is_unsupported === true) return [];

const attachment = (message.attachments || [])[0] || {};
const isEcho = !postback && message.is_echo === true;
const texto = String((postback ? postback.title : message.text) || '').trim();
const anexoUrl = String(attachment.payload?.url || '').trim();
const tipoAnexo = attachment.type || '';

// Postback sem título não tem conteúdo aproveitável — descarta.
if (postback && texto === '') return [];

// ============================================================
// BOAS-VINDAS DE ANÚNCIO — GATILHO DO FOLLOW-UP RÁPIDO (1/2).
// Os anúncios click-to-DM têm mensagens de boas-vindas
// automáticas configuradas na Meta. Elas chegam como eco
// (is_echo: true) enviado pela própria conta. Se passassem
// adiante, o Verificar Intervenção pausava o agente (falsa
// intervenção). Em vez de só descartar, este eco agora marca
// o lead para o follow-up rápido: se em 5 minutos não houver
// nenhuma mensagem "recebida" dele, o ramo de follow-up envia
// uma mensagem fixa. A saudação é texto da CONTA (há anúncio
// de comunidade PT com saudação em inglês), então NÃO dá para
// detectar o idioma do cliente por ela — usa o padrão 'en'.
// Ecos do Samuel digitando qualquer outra coisa continuam
// pausando o agente normalmente.
// Para cobrir um anúncio novo com saudação fora do padrão,
// basta adicionar um trecho (minúsculas, sem acentos) à lista.
// ============================================================
const tiposMidia = ['image', 'audio', 'video', 'file'];
// Ecos de midia conservam autoria e sao comparados pelo ID do provedor.

// Sem texto e sem anexo não existe conteúdo útil — descarta.
if (texto === '' && anexoUrl === '') return [];

const canal = body.object === 'instagram' ? 'instagram' : 'messenger';
const senderId = messaging.sender?.id || '';
const recipientId = messaging.recipient?.id || '';
const clienteId = isEcho ? recipientId : senderId;

if (!clienteId) return [];

const mid = (postback ? postback.mid : message.mid) || '';

// === NOME DO PERFIL ===
// Vem da User Profile API da Meta, injetado pelo "Juntar Nome Meta"
// em body._nome_perfil. Se a busca falhou, fica vazio e nada quebra.
const nomePerfil = String(body._nome_perfil || '').trim();

// === ANÚNCIO / REFERRAL ===
// Quando o cliente chega por um anúncio click-to-DM, a Meta manda um objeto
// "referral" junto com a primeira mensagem (ou no messaging/postback).
const referral =
  message.referral ||
  messaging.referral ||
  (messaging.postback || {}).referral ||
  {};
const adsCtx = referral.ads_context_data || {};
const anuncio = (referral.ad_id || adsCtx.ad_title || referral.ref)
  ? {
      id: referral.ad_id || '', campanha_id:referral.campaign_id || adsCtx.campaign_id || '', conjunto_id:referral.adset_id || adsCtx.adset_id || '',
      titulo: adsCtx.ad_title || '',
      ref: referral.ref || '',
      origem: referral.source || '',
      foto: adsCtx.photo_url || '',
      video: adsCtx.video_url || ''
    }
  : null;

// Ignorar reacções automáticas/gifs de reação.
const ehReacaoAutomatica =
  isEcho === true && tipoAnexo === 'image' && !texto &&
  String(anexoUrl).includes('t59.2708-21') && String(anexoUrl).toLowerCase().includes('.gif');
if (ehReacaoAutomatica) return [];

let tipo = 'text';
let mimetype = '';
let conteudo = texto;

if (anexoUrl) {
  conteudo = anexoUrl;
  if (tipoAnexo === 'image') { tipo = 'image'; mimetype = 'image/jpeg'; }
  else if (tipoAnexo === 'audio') { tipo = 'audio'; mimetype = 'audio/mpeg'; }
  else if (tipoAnexo === 'video') { tipo = 'video'; mimetype = 'video/mp4'; }
  else if (tipoAnexo === 'file') { tipo = 'document'; mimetype = 'application/pdf'; }
  else { tipo = 'outro'; }
}

const identificador = canal + ':' + clienteId;
const conteudoEco = texto || anexoUrl || '';
const chaveConteudo = textoParaChave(conteudoEco) || 'sem_conteudo';
const redisNamespace = `lexia:novo_cliente:${canal}:v1`;
const ecoIaKey = `${redisNamespace}:eco_ia:${identificador}:${chaveConteudo}`;

return [{ json: { body: {
  _canal: canal, _lexia_transport:'meta', _provider_account_ref:String(entry.id || ''), _provider_timestamp:messaging.timestamp || entry.time || Date.now(),
  _identificador: identificador,
  _sender_id: clienteId,
  _meta_sender_id: senderId,
  _meta_recipient_id: recipientId,
  _meta_mid: mid,
  _meta_is_echo: isEcho,
  _meta_conteudo_eco: conteudoEco,
  _meta_eco_ia_key: ecoIaKey,
  _anuncio: anuncio,
  phone: clienteId,
  owner: clienteId,
  name: isEcho ? '' : nomePerfil,
  text: conteudo,
  message: {
    type: tipo,
    messageType: tipo,
    text: conteudo,
    id: mid,
    messageid: mid,
    fromMe: isEcho,
    sender: clienteId,
    sender_pn: clienteId,
    content: {
      text: conteudo,
      URL: anexoUrl || conteudo,
      mimetype
    }
  },
  chat: { name: isEcho ? '' : nomePerfil, phone: clienteId }
}} }];

