const items=await(async()=>{// ============================================================
// PREPARAR PAYLOAD CÉREBRO — v2 (intervenção humana no histórico)
//
// NOVO na v2:
//   - Cada mensagem do histórico agora leva o campo "autor":
//       'cliente'        → mensagem recebida do lead
//       'equipe_humana'  → enviada manualmente pela equipe
//                          (Samuel pelo celular; origem = 'humano')
//       'agente_ia'      → enviada pela Carol (IA)
//     Antes, o campo "origem" era descartado aqui e o Cérebro não
//     tinha como saber que o Samuel interveio — respondia sem
//     contexto do que a equipe já tinha combinado com o lead.
//   - Bloco "intervencao_humana" no payload: diz se houve
//     intervenção nas últimas 30 mensagens e se ela é MAIS RECENTE
//     que a última resposta da IA (caso crítico: Samuel falou por
//     último e a Carol está retomando agora).
//
// O resto é idêntico à versão anterior.
// ============================================================
function obterNode(nome, fallback = {}) {
  try {
    return $(nome).first().json || fallback;
  } catch (e) {
    return fallback;
  }
}
function parseJsonSeguro(valor, fallback = {}) {
  if (!valor) return fallback;
  if (typeof valor === 'object') return valor;
  try {
    return JSON.parse(valor);
  } catch (e) {
    return fallback;
  }
}
function normalizarHistorico(valor) {
  const parsed = parseJsonSeguro(valor, valor);
  if (Array.isArray(parsed)) return parsed;
  if (parsed && Array.isArray(parsed.data)) return parsed.data;
  return [];
}
const normalizar = obterNode('Normalizar Dados Operacionais');
const config = obterNode('Config Cliente Lexia');
const contacto = obterNode('Unificar Contacto');
const pacote = obterNode('Preparar Pacote de Contexto');
const contexto = obterNode('Preparar Contexto Activo');
const mensagemAgente = obterNode('Mensagem para o Agente');
const historicoBruto = normalizarHistorico(pacote.historico_mensagens);

// --- autor de cada mensagem (NOVO v2) ---
function autorDe(m) {
  const direccao = m.direccao || m.direcao || '';
  const origem = String(m.origem || '');
  if (direccao === 'recebida') return 'cliente';
  if (origem === 'humano') return 'equipe_humana';
  return 'agente_ia';
}

const historicoLimpo = historicoBruto
  .map(m => ({
    autor: autorDe(m),
    direccao: m.direccao || m.direcao || '',
    tipo: m.tipo || 'texto',
    conteudo: m.conteudo || '',
    criado_em: m.criado_em || m.created_at || ''
  }))
  .filter(m => m.conteudo)
  .sort((a, b) => String(a.criado_em).localeCompare(String(b.criado_em)))
  .slice(-30);

// --- resumo da intervenção humana (NOVO v2) ---
const msgsEquipe = historicoLimpo.filter(m => m.autor === 'equipe_humana');
let ultimaIA = '';
let ultimaEquipe = '';
for (const m of historicoLimpo) {
  if (m.autor === 'agente_ia') ultimaIA = m.criado_em;
  if (m.autor === 'equipe_humana') ultimaEquipe = m.criado_em;
}
const intervencaoHumana = {
  houve: msgsEquipe.length > 0,
  total_mensagens_equipe: msgsEquipe.length,
  ultima_em: ultimaEquipe || null,
  // true quando a equipe falou DEPOIS da última resposta da IA —
  // é o caso em que a Carol precisa retomar de onde o Samuel parou
  mais_recente_que_ia: !!ultimaEquipe && (!ultimaIA || String(ultimaEquipe) > String(ultimaIA))
};

// === ANÚNCIO / REFERRAL ===
// Busca o anúncio extraído pelo Normalizar Entrada Meta (só existe em mensagens
// do Instagram/Messenger; no WhatsApp o try/catch devolve vazio sem quebrar).
let anuncio = null;
try {
  const metaBody = $('Normalizar Entrada Meta Omnichannel').first().json.body || {};
  if (metaBody._anuncio && (metaBody._anuncio.id || metaBody._anuncio.titulo || metaBody._anuncio.ref)) {
    anuncio = metaBody._anuncio;
  }
} catch (e) {
  anuncio = null;
}
const mensagemBase =
  pacote.mensagem_actual ||
  mensagemAgente.mensagens ||
  normalizar.conteudo_mensagem ||
  '';
let notaAnuncio = '';
if (anuncio) {
  const partes = [];
  if (anuncio.titulo) partes.push(`título: "${anuncio.titulo}"`);
  if (anuncio.id) partes.push(`id: ${anuncio.id}`);
  if (anuncio.ref) partes.push(`ref: ${anuncio.ref}`);
  notaAnuncio =
