function limparTexto(valor) {
  return String(valor || '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function parseJsonSeguro(raw) {
  if (raw && typeof raw === 'object') return raw;

  const texto = limparTexto(raw);

  try {
    return JSON.parse(texto);
  } catch (e) {}

  const match = texto.match(/\{[\s\S]*\}/);

  if (match) {
    try {
      return JSON.parse(match[0]);
    } catch (e) {}
  }

  return null;
}

function asArray(valor) {
  if (Array.isArray(valor)) return valor;
  if (valor === null || valor === undefined) return [];
  if (typeof valor === 'string' && valor.trim()) return [valor.trim()];
  return [];
}

function normalizarEntrega(entrega, index = 0) {
  if (!entrega) return null;

  if (typeof entrega === 'string') {
    const texto = limparTexto(entrega);
    if (!texto) return null;

    return {
      id: `entrega_${index + 1}`,
      ordem: index + 1,
      tipo: 'texto',
      texto
    };
  }

  const tipo = String(entrega.tipo || entrega.type || '').trim().toLowerCase();

  if (tipo === 'texto' || tipo === 'text' || tipo === 'mensagem') {
    const texto = limparTexto(
      entrega.texto ||
      entrega.text ||
      entrega.mensagem ||
      entrega.conteudo ||
      ''
    );

    if (!texto) return null;

    return {
      id: entrega.id || `entrega_${index + 1}`,
      ordem: Number(entrega.ordem || index + 1),
      tipo: 'texto',
      texto
    };
  }

  if (tipo === 'imagem' || tipo === 'image' || tipo === 'foto') {
    const url = String(
      entrega.url ||
      entrega.media_url ||
      entrega.image_url ||
      entrega.url_foto ||
      entrega.conteudo ||
      ''
    ).trim();

    if (!url) return null;

    return {
      id: entrega.id || `entrega_${index + 1}`,
      ordem: Number(entrega.ordem || index + 1),
      tipo: 'imagem',
      url,
      legenda: limparTexto(entrega.legenda || entrega.caption || entrega.descricao || '')
    };
  }

  if (tipo === 'documento' || tipo === 'document' || tipo === 'pdf') {
    const url = String(entrega.url || entrega.file_url || entrega.conteudo || '').trim();

    if (!url) return null;

    return {
      id: entrega.id || `entrega_${index + 1}`,
      ordem: Number(entrega.ordem || index + 1),
      tipo: 'documento',
      url,
      nome_arquivo: entrega.nome_arquivo || entrega.filename || '',
