// ============================================================
// ADAPTAR ENTRADA Z-API — v3 (ignora notificações REVOKE / @lid)
// Fica entre o Webhook WhatsApp Omnichannel e a Entrada
// Unificada. Traduz o payload da Z-API para o formato interno
// que o resto do workflow já entende (o "dialeto uazapi":
// body.message.content.URL, messageType, chat.phone, etc.).
//
// Também é a primeira barreira:
//   - fromApi === true  -> mensagem enviada pela própria Carol
//     via API: descarta (senão o agente responderia a si mesmo
//     ou se auto-pausaria como "intervenção").
//   - fromMe === true e fromApi === false -> Samuel digitou no
//     celular: PASSA, vira intervenção humana (pausa de 15 min).
//   - grupos, canais, status, edições e broadcasts: descarta.
//   - sticker/reação: passam marcados como StickerMessage /
//     ReactionMessage — o Filtro de Mensagens já os corta.
//
// v2: quando a mensagem vem de anúncio click-to-WhatsApp,
// a Z-API entrega o bloco externalAdReply (título, texto, ID e
// URL do anúncio). Este node lê esse bloco e classifica o
// TEMA do anúncio de forma determinística:
//   - 'laser'     -> anúncio de depilação a laser
//   - 'avaliacao' -> anúncio de avaliação de pele gratuita
//   - ''          -> qualquer outro anúncio / orgânico -> fluxo
//                    normal de texto, sem áudio.
// O resultado sai em body._anuncio_tema (e os dados crus em
// body._anuncio) e é usado pelo Preparar Follow-up para escolher
// o áudio do Samuel no follow-up de 1h.
//
// NOVO na v3: dois filtros determinísticos a mais:
//   1. p.notification preenchido (ex.: "REVOKE" = mensagem
//      apagada) -> descarta. Notificações nunca são mensagens
//      de verdade (nem têm campo text) e vinham passando com
//      fromMe:true, gerando "intervenção humana" falsa em
//      conversas que nem existem.
//   2. phone terminando em "@lid" (identificador interno do
//      WhatsApp, não é número real) -> descarta. Sem número
//      real não há conversa para associar.
// ============================================================

// ------------------------------------------------------------
// MAPA MANUAL POR ID DE ANÚNCIO (prioridade máxima).
// Se um anúncio específico não for classificado direito pelas
// palavras-chave, basta colocar o sourceId dele aqui.
// O sourceId aparece no webhook em body.externalAdReply.sourceId.
// Exemplo:
//   'REMOVED_CONTACT': 'avaliacao',
// ------------------------------------------------------------
const TEMA_POR_ANUNCIO = {
  // 'ID_DO_ANUNCIO': 'laser' | 'avaliacao',
};

function normalizar(texto) {
  return String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Classifica o tema do anúncio pelo título + texto.
// Só devolve um tema quando o sinal é claro e único;
// na dúvida devolve '' (fluxo normal, sem áudio).
function detectarTema(ad) {
  const idAnuncio = String(ad.sourceId || '');
  if (TEMA_POR_ANUNCIO[idAnuncio]) return TEMA_POR_ANUNCIO[idAnuncio];

  const t = ' ' + normalizar(String(ad.title || '') + ' ' + String(ad.body || '')) + ' ';

  const ehLaser =
    /\b(depilacao a laser|depilacion laser|laser hair removal|\blaser\b)\b/.test(t);

  const ehAvaliacao =
    /\b(avaliacao de pele|avaliacao gratuita|avaliacao de pele gratuita|skin (evaluation|assessment|analysis)|free skin|evaluacion de piel|analise de pele)\b/.test(t);

  if (ehLaser && !ehAvaliacao) return 'laser';
  if (ehAvaliacao && !ehLaser) return 'avaliacao';
  return '';
}

const saida = [];

for (const item of $input.all()) {
  const p = item.json.body || item.json || {};

  // Só eventos de mensagem (ignora qualquer outro tipo de evento)
  if (String(p.type || '') !== 'ReceivedCallback') continue;

  // NOVO v3: notificações (REVOKE = mensagem apagada, etc.)
  // não são mensagens de verdade — nunca entram.
  if (p.notification) continue;

  // Mensagem enviada pela própria API (a Carol): nunca entra
  // Automatic echoes are compared with the durable provider-ID ledger.

  // Ruído que não é conversa privada normal
  if (p.isGroup === true) continue;
  if (p.isNewsletter === true) continue;
  if (p.isStatusReply === true) continue;
  if (p.broadcast === true) continue;
  if (p.isEdit === true) continue;

  // NOVO v3: "@lid" é identificador interno do WhatsApp,
  // não é número de telefone real — sem número, sem conversa.
  const phoneCru = String(p.phone || '');
  if (phoneCru.endsWith('@lid')) continue;

  const texto = String((p.text && p.text.message) || '');

  // Descobre o tipo e a mídia
  let tipo = 'text';
  let messageType = 'Conversation';
  let url = '';
  let mime = '';
  let caption = '';

  if (p.image) {
    tipo = 'image';
    messageType = 'ImageMessage';
    url = String(p.image.imageUrl || '');
    mime = String(p.image.mimeType || '');
    caption = String(p.image.caption || '');
  } else if (p.audio) {
    tipo = 'audio';
    messageType = 'AudioMessage';
    url = String(p.audio.audioUrl || '');
    mime = String(p.audio.mimeType || '');
  } else if (p.video) {
    tipo = 'video';
    messageType = 'VideoMessage';
    url = String(p.video.videoUrl || '');
    mime = String(p.video.mimeType || '');
    caption = String(p.video.caption || '');
  } else if (p.document) {
    tipo = 'document';
    messageType = 'DocumentMessage';
    url = String(p.document.documentUrl || '');
    mime = String(p.document.mimeType || '');
    caption = String(p.document.title || p.document.fileName || '');
  } else if (p.sticker) {
    tipo = 'outro';
    messageType = 'StickerMessage'; // o Filtro de Mensagens corta
  } else if (p.reaction) {
    tipo = 'outro';
    messageType = 'ReactionMessage'; // o Filtro de Mensagens corta
  } else if (!texto) {
    // contato, localização, enquete, etc. — sem texto útil
    tipo = 'outro';
    messageType = 'Unknown';
  }

  const telefone = phoneCru.replace(/[^0-9]/g, '');

  const body = { _lexia_transport: 'zapi', _provider_account_ref: String(p.instanceId || ''), _provider_timestamp: p.momment || Date.now(),
    _canal: 'whatsapp',
    phone: telefone,
    owner: telefone,
    chat: {
      phone: telefone,
      name: String(p.chatName || p.senderName || '')
    },
    message: {
      fromMe: p.fromMe === true,
      type: tipo,
      messageType,
      messageid: String(p.messageId || ''),
      sender: telefone,
      senderName: String(p.senderName || ''),
      text: texto || caption || '',
      mimetype: mime,
      content: {
        URL: url,
        mimetype: mime,
        text: texto || caption || ''
      }
    },
    _zapi: {
      from_api: p.fromApi === true,
      momment: p.momment || null,
      instance_id: String(p.instanceId || ''),
      connected_phone: String(p.connectedPhone || ''),
      message_id: String(p.messageId || '')
    }
  };

  // --------------------------------------------------------
  // v2: anúncio de origem (click-to-WhatsApp).
  // Só existe na primeira mensagem que o cliente manda a
  // partir do anúncio — nas mensagens seguintes o bloco não
  // vem, e aí simplesmente não marcamos nada.
  // --------------------------------------------------------
  const ad = p.externalAdReply || null;
  if (ad && typeof ad === 'object') {
    body._anuncio = {
      source_id: String(ad.sourceId || ''),
      titulo: String(ad.title || ''),
      corpo: String(ad.body || ''),
      source_url: String(ad.sourceUrl || ''),
      source_app: String(ad.sourceApp || '')
    };
    body._anuncio_tema = detectarTema(ad);
  }

  saida.push({ json: { body } });
}

return saida;

