={{ (() => {
  const canal = $("Normalizar Dados Operacionais").first().json.canal || 'whatsapp';
  const item = $('Loop Over Items - Entregas').item.json;
  const entrega = item.entregas || item;

  const tipo = String(entrega.tipo || 'texto').toLowerCase();

  const recipient = String(
    entrega.telefone ||
    $("Preparar Saída Omnichannel").first().json.telefone ||
    $("Normalizar Dados Operacionais").first().json.telefone ||
    $("Normalizar Dados Operacionais").first().json.sender_id ||
    ''
  );

  const texto = String(
    entrega.texto ||
    entrega.mensagem ||
    entrega.text ||
    ''
  );

  const url = String(
    entrega.url ||
    entrega.media_url ||
    entrega.url_foto ||
    ''
  );

  const legenda = String(
    entrega.legenda ||
    entrega.caption ||
    ''
  );

  if (canal === 'whatsapp') {
    const telefone = recipient.replace(/[^0-9]/g, '');
    const digitando = 0; // Nenhuma espera depois do gate.
if(tipo==='documento')return JSON.stringify({phone:telefone,document:url,fileName:entrega.nome_arquivo||'documento.pdf'});

    if (tipo === 'imagem' || tipo === 'image' || tipo === 'foto') {
      return JSON.stringify({
        phone: telefone,
        image: url,
        caption: legenda,
        delayTyping: digitando
      });
    }

    return JSON.stringify({
      phone: telefone,
      message: texto,
      delayTyping: digitando
    });
  }

  if (tipo === 'documento') return JSON.stringify({recipient:{id:recipient},message:{attachment:{type:'file',payload:{url,is_reusable:true}}}});
  if (tipo === 'imagem' || tipo === 'image' || tipo === 'foto') {
    return JSON.stringify({
      recipient: {
        id: recipient
      },
      message: {
        attachment: {
          type: 'image',
          payload: {
            url: url,
            is_reusable: true
          }
        }
      }
    });
  }

  return JSON.stringify({
    recipient: {
      id: recipient
    },
    message: {
      text: texto
    }
  });
})() }}

